import * as THREE from 'three';
import { WAVE_GLSL, waveHeight } from './waves.js';
import {
  makeCloudTexture,
  makeGlowTexture,
  makeFoamTile,
  rng,
} from './textures.js';

export const SUN_DIR = new THREE.Vector3(-0.55, 0.205, -0.81).normalize();

const COLORS = {
  skyZenith: '#315f80',
  skyUpper: '#78a2b6',
  skyHorizonWarm: '#ffd0a0',
  skyHorizonCool: '#c8c3cb',
  fog: '#ecc6aa',
  waterDeep: '#0a424f',
  waterShallow: '#1f8081',
  foam: '#fff7ea',
};

function wrap(value, min, max) {
  const range = max - min;
  return ((((value - min) % range) + range) % range) + min;
}

function createSky() {
  const uniforms = {
    uSunDir: { value: SUN_DIR.clone() },
    uZenith: { value: new THREE.Color(COLORS.skyZenith) },
    uUpper: { value: new THREE.Color(COLORS.skyUpper) },
    uHorizonWarm: { value: new THREE.Color(COLORS.skyHorizonWarm) },
    uHorizonCool: { value: new THREE.Color(COLORS.skyHorizonCool) },
  };

  const material = new THREE.ShaderMaterial({
    uniforms,
    side: THREE.BackSide,
    depthWrite: false,
    depthTest: false,
    fog: false,
    vertexShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vDir = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uSunDir;
      uniform vec3 uZenith;
      uniform vec3 uUpper;
      uniform vec3 uHorizonWarm;
      uniform vec3 uHorizonCool;
      varying vec3 vDir;

      void main() {
        vec3 d = normalize(vDir);
        float h = max(d.y, 0.0);
        vec3 sunAzimuth = normalize(vec3(uSunDir.x, 0.0, uSunDir.z));
        vec3 dirAzimuth = normalize(vec3(d.x, 0.0, d.z));
        float sunAz = pow(max(dot(dirAzimuth, sunAzimuth), 0.0), 2.6);
        vec3 horizon = mix(uHorizonCool, uHorizonWarm, sunAz);

        vec3 col = mix(horizon, uUpper, smoothstep(0.0, 0.3, h));
        col = mix(col, uZenith, smoothstep(0.17, 0.9, h));

        float sd = max(dot(d, normalize(uSunDir)), 0.0);
        col += vec3(1.0, 0.86, 0.64) * pow(sd, 1600.0) * 7.0;
        col += vec3(1.0, 0.68, 0.42) * pow(sd, 64.0) * 0.55;
        col += vec3(1.0, 0.72, 0.45) * pow(sd, 8.0) * 0.10;
        col += vec3(1.0, 0.52, 0.28) * exp(-pow((h - 0.025) / 0.055, 2.0)) * 0.055 * (0.25 + sunAz);

        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });

  const mesh = new THREE.Mesh(new THREE.SphereGeometry(470, 48, 32), material);
  mesh.renderOrder = -10;
  mesh.frustumCulled = false;
  return mesh;
}

function createOcean() {
  const uniforms = {
    uTime: { value: 0 },
    uSunDir: { value: SUN_DIR.clone() },
    uDeep: { value: new THREE.Color(COLORS.waterDeep) },
    uShallow: { value: new THREE.Color(COLORS.waterShallow) },
    uHorizonWarm: { value: new THREE.Color(COLORS.skyHorizonWarm) },
    uHorizonCool: { value: new THREE.Color(COLORS.skyHorizonCool) },
  };

  const material = new THREE.ShaderMaterial({
    uniforms,
    fog: false,
    vertexShader: /* glsl */ `
      uniform float uTime;
      varying vec3 vWorld;
      varying vec3 vNormal;
      varying float vHeight;
      ${WAVE_GLSL}
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        float h = oceanHeight(wp.xz, uTime);
        wp.y += h;
        vec2 g = oceanGradient(wp.xz, uTime);
        vNormal = normalize(vec3(-g.x, 1.0, -g.y));
        vHeight = h;
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform float uTime;
      uniform vec3 uSunDir;
      uniform vec3 uDeep;
      uniform vec3 uShallow;
      uniform vec3 uHorizonWarm;
      uniform vec3 uHorizonCool;
      varying vec3 vWorld;
      varying vec3 vNormal;
      varying float vHeight;

      float hash21(vec2 p) {
        p = fract(p * vec2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
      }
      float vnoise(vec2 p) {
        vec2 i = floor(p);
        vec2 f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        float a = hash21(i);
        float b = hash21(i + vec2(1.0, 0.0));
        float c = hash21(i + vec2(0.0, 1.0));
        float d = hash21(i + vec2(1.0, 1.0));
        return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
      }
      float fbm(vec2 p) {
        float v = 0.0;
        float a = 0.5;
        mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
        for (int i = 0; i < 4; i++) {
          v += a * vnoise(p);
          p = rot * p * 2.03 + 13.1;
          a *= 0.5;
        }
        return v;
      }

      void main() {
        vec3 V = normalize(cameraPosition - vWorld);
        vec3 N = normalize(vNormal);
        vec2 q = vWorld.xz;
        float t = uTime;

        // fine ripples
        float c1 = cos(q.x * 1.9 + q.y * 0.8 + t * 1.55);
        float c2 = cos(q.x * 3.7 - q.y * 2.4 - t * 2.15);
        float c3 = cos(q.x * 7.3 + q.y * 5.1 + t * 3.2);
        vec2 detail = vec2(1.9, 0.8) * c1 * 0.012
                    + vec2(3.7, -2.4) * c2 * 0.0048
                    + vec2(7.3, 5.1) * c3 * 0.0016;
        N = normalize(N + vec3(-detail.x, 0.0, -detail.y));

        float facing = clamp(dot(N, V), 0.0, 1.0);
        float fres = pow(1.0 - facing, 4.0);
        fres = mix(0.045, 1.0, fres);

        vec3 R = reflect(-V, N);
        float up = clamp(R.y, 0.0, 1.0);
        vec3 skyRef = mix(uHorizonWarm, vec3(0.30, 0.55, 0.66), smoothstep(0.0, 0.55, up));

        float crestMix = smoothstep(-0.32, 0.5, vHeight);
        vec3 water = mix(uDeep, uShallow, crestMix * 0.5);
        water = mix(water, skyRef * 0.75, fres * 0.8);

        vec3 L = normalize(uSunDir);
        vec3 H = normalize(L + V);
        float nh = max(dot(N, H), 0.0);
        float spec = pow(nh, 420.0) * 4.2 * (0.6 + 0.8 * fbm(q * 7.0 + t * 0.25));
        float sheen = pow(nh, 16.0) * 0.22;
        vec3 sunTint = vec3(1.0, 0.68, 0.38);
        water += sunTint * (spec + sheen * max(dot(N, L), 0.0));

        // whitecaps: broad crest bands broken up with noise
        float n1 = fbm(q * 0.5 + vec2(t * 0.045, -t * 0.025));
        float n2 = fbm(q * 2.2 + vec2(-t * 0.09, t * 0.06));
        float crest = smoothstep(0.16, 0.44, vHeight + (n1 - 0.5) * 0.22);
        float broken = smoothstep(0.4, 0.74, n2 + crest * 0.24);
        float foam = crest * broken;
        float streak = smoothstep(0.63, 0.9, fbm(vec2(q.x * 0.22 + q.y * 0.06, q.y * 1.3 - t * 0.12)));
        foam += streak * smoothstep(-0.05, 0.28, vHeight) * 0.18;
        float farFoam = 1.0 - smoothstep(110.0, 250.0, distance(cameraPosition, vWorld));
        foam = clamp(foam, 0.0, 0.9) * farFoam;
        water = mix(water, vec3(0.94, 0.96, 0.94), foam);

        // atmospheric haze, warmer toward the sun
        vec3 viewDir = normalize(vWorld - cameraPosition);
        vec3 viewAz = normalize(vec3(viewDir.x, 0.0, viewDir.z));
        vec3 sunAz = normalize(vec3(L.x, 0.0, L.z));
        float towardSun = pow(max(dot(viewAz, sunAz), 0.0), 2.0);
        vec3 hazeCol = mix(uHorizonCool, uHorizonWarm, towardSun);
        float dist = distance(cameraPosition, vWorld);
        float haze = 1.0 - exp(-pow(dist * 0.0058, 2.0));
        water = mix(water, hazeCol, haze);

        gl_FragColor = vec4(water, 1.0);
      }
    `,
  });

  const geometry = new THREE.PlaneGeometry(560, 560, 220, 220);
  geometry.rotateX(-Math.PI / 2);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  return { mesh, uniforms };
}

function makeCloud(rand, scale) {
  const group = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({
    color: new THREE.Color('#f5d4c4'),
    roughness: 1.0,
    metalness: 0.0,
    emissive: new THREE.Color('#77372f'),
    emissiveIntensity: 0.32,
  });
  const puffGeo = new THREE.SphereGeometry(1, 16, 12);
  const count = 5 + Math.floor(rand() * 5);
  for (let i = 0; i < count; i++) {
    const puff = new THREE.Mesh(puffGeo, mat);
    const x = (rand() - 0.5) * 2.4;
    const y = (rand() - 0.3) * 0.55;
    const z = (rand() - 0.5) * 0.9;
    const s = 0.4 + rand() * 0.55;
    puff.position.set(x, y, z);
    puff.scale.set(s * (0.9 + rand() * 0.4), s * (0.55 + rand() * 0.3), s * (0.8 + rand() * 0.3));
    group.add(puff);
  }
  group.scale.setScalar(scale);
  return group;
}

function createPalm(height, lean, rand) {
  const group = new THREE.Group();
  const trunkMat = new THREE.MeshStandardMaterial({
    color: '#4d4a3f',
    roughness: 1,
  });
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.3, height, 6), trunkMat);
  trunk.position.y = height * 0.5;
  trunk.rotation.z = lean;
  group.add(trunk);

  const leafMat = new THREE.MeshStandardMaterial({
    color: '#284b48',
    roughness: 0.95,
    side: THREE.DoubleSide,
  });
  const leafGeo = new THREE.ConeGeometry(0.75, 3.6, 3, 1, true);
  for (let i = 0; i < 7; i++) {
    const leaf = new THREE.Mesh(leafGeo, leafMat);
    leaf.position.set(Math.sin(lean) * height, height, 0);
    leaf.rotation.z = Math.PI * 0.32 + lean;
    leaf.rotation.y = (i / 7) * Math.PI * 2 + rand() * 0.3;
    leaf.scale.set(1, 1, 0.18);
    group.add(leaf);
  }
  return group;
}

function createIsland(seed, opts = {}) {
  const rand = rng(seed);
  const group = new THREE.Group();
  const rockMat = new THREE.MeshStandardMaterial({
    color: '#4d6873',
    roughness: 1,
    metalness: 0,
    emissive: new THREE.Color('#1c2c34'),
    emissiveIntensity: 0.55,
  });
  const hillMat = new THREE.MeshStandardMaterial({
    color: '#516a6d',
    roughness: 1,
    metalness: 0,
    emissive: new THREE.Color('#25332f'),
    emissiveIntensity: 0.5,
  });

  const base = new THREE.Mesh(new THREE.SphereGeometry(1, 24, 16), rockMat);
  base.scale.set(opts.width ?? 26, 6, opts.depth ?? 15);
  base.position.y = -1.5;
  group.add(base);

  const hillCount = 2 + Math.floor(rand() * 2);
  for (let i = 0; i < hillCount; i++) {
    const h = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 12), hillMat);
    h.scale.set(8 + rand() * 10, 7 + rand() * 8, 8 + rand() * 6);
    h.position.set((rand() - 0.5) * 22, 2 + rand() * 3, (rand() - 0.5) * 10);
    group.add(h);
  }

  if (opts.palms !== false) {
    for (let i = 0; i < 3; i++) {
      const palm = createPalm(7 + rand() * 5, (rand() - 0.5) * 0.22, rand);
      palm.position.set((rand() - 0.5) * 20, 5 + rand() * 3, (rand() - 0.5) * 8);
      group.add(palm);
    }
  }

  if (opts.lighthouse) {
    const towerMat = new THREE.MeshStandardMaterial({ color: '#efe4d2', roughness: 0.8 });
    const redMat = new THREE.MeshStandardMaterial({ color: '#c95b43', roughness: 0.8 });
    const tower = new THREE.Group();
    const body = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 1.4, 8, 12), towerMat);
    body.position.y = 4;
    tower.add(body);
    const stripe = new THREE.Mesh(new THREE.CylinderGeometry(1.05, 1.15, 1.1, 12), redMat);
    stripe.position.y = 5.6;
    tower.add(stripe);
    const roof = new THREE.Mesh(new THREE.ConeGeometry(1.15, 1.6, 12), redMat);
    roof.position.y = 8.8;
    tower.add(roof);
    const lamp = new THREE.Mesh(
      new THREE.SphereGeometry(0.42, 12, 10),
      new THREE.MeshBasicMaterial({ color: '#ffdba0' }),
    );
    lamp.position.y = 7.9;
    tower.add(lamp);
    tower.position.set(8, 7, -1);
    group.add(tower);

    const glow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: makeGlowTexture(),
        color: '#ffce8a',
        transparent: true,
        opacity: 0.55,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        fog: false,
      }),
    );
    glow.position.set(8, 14.9, -1);
    glow.scale.setScalar(8);
    group.add(glow);
  }

  return group;
}

function createSailboat() {
  const group = new THREE.Group();
  const hullMat = new THREE.MeshStandardMaterial({ color: '#334f58', roughness: 0.7 });
  const sailMat = new THREE.MeshBasicMaterial({
    color: '#ffe7cb',
    side: THREE.DoubleSide,
    fog: true,
  });

  const hull = new THREE.Mesh(new THREE.CapsuleGeometry(0.7, 3.6, 5, 10), hullMat);
  hull.rotation.z = Math.PI / 2;
  hull.scale.set(1, 1, 0.55);
  hull.position.y = 0.4;
  group.add(hull);

  const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.08, 6, 6), hullMat);
  mast.position.set(0.15, 3.4, 0);
  group.add(mast);

  const sailShape = new THREE.Shape();
  sailShape.moveTo(0, 0);
  sailShape.lineTo(0, 5.2);
  sailShape.quadraticCurveTo(1.8, 3.4, 1.95, 0.1);
  sailShape.closePath();
  const sailGeo = new THREE.ShapeGeometry(sailShape);
  sailGeo.rotateY(Math.PI / 2);
  const sail = new THREE.Mesh(sailGeo, sailMat);
  sail.position.set(0.12, 1.2, 0);
  group.add(sail);

  const jibShape = new THREE.Shape();
  jibShape.moveTo(0, 0.9);
  jibShape.lineTo(-0.3, 4.9);
  jibShape.quadraticCurveTo(-1.7, 3.2, -1.9, 0.4);
  jibShape.closePath();
  const jibGeo = new THREE.ShapeGeometry(jibShape);
  jibGeo.rotateY(Math.PI / 2);
  const jib = new THREE.Mesh(jibGeo, sailMat);
  jib.position.set(0.18, 1.2, 0.02);
  group.add(jib);

  group.scale.setScalar(1.7);
  return group;
}

function createGull(rand) {
  const group = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({
    color: '#4c565b',
    side: THREE.DoubleSide,
    fog: true,
  });
  const wingShape = new THREE.Shape();
  wingShape.moveTo(0, 0);
  wingShape.quadraticCurveTo(0.9, 0.22, 1.55, -0.05);
  wingShape.quadraticCurveTo(0.9, -0.12, 0, -0.12);
  wingShape.closePath();
  const wingGeo = new THREE.ShapeGeometry(wingShape);

  const body = new THREE.Mesh(new THREE.SphereGeometry(0.13, 8, 6), mat);
  body.scale.set(0.7, 0.5, 2.0);
  group.add(body);

  const wr = new THREE.Mesh(wingGeo, mat);
  wr.rotation.y = -Math.PI / 2;
  wr.position.set(0, 0, 0);
  const wl = new THREE.Mesh(wingGeo, mat);
  wl.rotation.y = Math.PI / 2;
  wl.scale.x = -1;
  wl.position.set(0, 0, 0);
  group.add(wr, wl);

  group.userData = {
    wr,
    wl,
    phase: rand() * Math.PI * 2,
    speed: 0.7 + rand() * 0.6,
  };
  return group;
}

export function createEnvironment(scene, camera) {
  scene.fog = new THREE.FogExp2(COLORS.fog, 0.0058);

  const sky = createSky();
  scene.add(sky);

  const { mesh: ocean, uniforms: oceanUniforms } = createOcean();
  scene.add(ocean);

  const sunGlow = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: makeGlowTexture(),
      color: '#ffd7a4',
      transparent: true,
      opacity: 0.85,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      depthTest: true,
      fog: false,
    }),
  );
  sunGlow.scale.setScalar(95);
  scene.add(sunGlow);

  // ------------------------------------------------------------------ lights
  const hemi = new THREE.HemisphereLight(0xbfe4f2, 0x3b686d, 1.15);
  scene.add(hemi);

  const key = new THREE.DirectionalLight(0xffd0a0, 3.1);
  key.position.copy(SUN_DIR).multiplyScalar(90);
  scene.add(key);
  scene.add(key.target);

  const fill = new THREE.DirectionalLight(0xa6d8e9, 1.15);
  fill.position.set(20, 18, 26);
  scene.add(fill);
  scene.add(fill.target);

  const rim = new THREE.DirectionalLight(0xffb37a, 0.85);
  rim.position.set(-22, 8, -8);
  scene.add(rim);
  scene.add(rim.target);

  // ------------------------------------------------------------------ clouds
  const rand = rng(2024);
  const clouds = [];
  const cloudDefs = [
    [-110, 42, -180, 11],
    [40, 56, -230, 15],
    [150, 38, -160, 9],
    [240, 62, -260, 16],
    [-210, 50, -120, 10],
    [90, 34, -140, 7],
  ];
  for (const [x, y, z, s] of cloudDefs) {
    const cloud = makeCloud(rand, s);
    cloud.userData = { baseX: x, baseY: y, baseZ: z, drift: 0.4 + rand() * 0.7 };
    scene.add(cloud);
    clouds.push(cloud);
  }

  // ------------------------------------------------------------- islands
  const islands = [];
  const islandDefs = [
    { x: -95, z: -210, seed: 12, opts: { width: 32, depth: 16 } },
    { x: 125, z: -260, seed: 27, opts: { width: 24, depth: 14, lighthouse: true } },
    { x: 25, z: -180, seed: 41, opts: { width: 14, depth: 9, palms: false } },
  ];
  for (const def of islandDefs) {
    const island = createIsland(def.seed, def.opts);
    island.userData = { baseX: def.x, baseZ: def.z };
    island.position.set(def.x, -1.2, def.z);
    scene.add(island);
    islands.push(island);
  }

  const boat = createSailboat();
  boat.userData = { baseX: 55, baseZ: -150 };
  boat.position.set(55, 0, -150);
  scene.add(boat);

  // ---------------------------------------------------------------- gulls
  const gulls = [];
  for (let i = 0; i < 4; i++) {
    const gull = createGull(rand);
    gull.userData.baseX = -30 + rand() * 90;
    gull.userData.baseY = 8 + rand() * 12;
    gull.userData.baseZ = -35 - rand() * 45;
    gull.userData.drift = 1.5 + rand() * 2;
    gull.scale.setScalar(0.7 + rand() * 0.5);
    scene.add(gull);
    gulls.push(gull);
  }

  // high wispy clouds, as soft sprites
  const cloudTex = makeCloudTexture();
  const wisps = [];
  for (let i = 0; i < 7; i++) {
    const mat = new THREE.SpriteMaterial({
      map: cloudTex,
      color: '#ffd9c1',
      transparent: true,
      opacity: 0.45,
      depthWrite: false,
      fog: false,
    });
    const sprite = new THREE.Sprite(mat);
    sprite.userData = {
      baseX: -300 + rand() * 600,
      baseY: 70 + rand() * 55,
      baseZ: -260 - rand() * 120,
      scale: 90 + rand() * 80,
    };
    sprite.scale.set(sprite.userData.scale, sprite.userData.scale * 0.35, 1);
    scene.add(sprite);
    wisps.push(sprite);
  }

  // Small, thrown-away foam texture used to give the sea some sparkle
  const foamSparkle = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: makeFoamTile(),
      transparent: true,
      opacity: 0.0,
      depthWrite: false,
    }),
  );
  foamSparkle.visible = false;
  scene.add(foamSparkle);

  const clockStart = 0;

  function update(t, dt, boardPos) {
    oceanUniforms.uTime.value = t;
    sky.position.copy(camera.position);
    sunGlow.position.copy(camera.position).addScaledVector(SUN_DIR, 380);

    ocean.position.set(boardPos.x, 0, boardPos.z);

    key.position.copy(boardPos).addScaledVector(SUN_DIR, 90);
    key.target.position.copy(boardPos);
    fill.position.set(boardPos.x + 24, boardPos.y + 20, boardPos.z + 34);
    fill.target.position.copy(boardPos);
    rim.position.set(boardPos.x - 24, boardPos.y + 7, boardPos.z - 12);
    rim.target.position.copy(boardPos);

    for (const cloud of clouds) {
      const d = cloud.userData;
      cloud.position.x = camera.position.x + wrap(d.baseX - camera.position.x, -280, 280);
      cloud.position.y = d.baseY + Math.sin(t * 0.05 + d.baseX) * 1.5;
      cloud.position.z = d.baseZ;
      cloud.rotation.y = Math.sin(t * 0.02 + d.baseX) * 0.1;
    }

    for (const island of islands) {
      const d = island.userData;
      island.position.x = camera.position.x + wrap(d.baseX - camera.position.x, -300, 300);
      island.position.z = d.baseZ;
    }

    const bd = boat.userData;
    boat.position.x = camera.position.x + wrap(bd.baseX + t * 0.16 - camera.position.x, -270, 270);
    boat.position.z = bd.baseZ;
    boat.position.y = Math.sin(t * 0.9) * 0.22 - 0.1;
    boat.rotation.z = Math.sin(t * 0.8 + 0.4) * 0.03;

    for (const gull of gulls) {
      const d = gull.userData;
      gull.position.x = camera.position.x + wrap(d.baseX + t * d.drift * 0.6 - camera.position.x, -55, 55);
      gull.position.y = d.baseY + Math.sin(t * 0.5 + d.phase) * 1.2;
      gull.position.z = d.baseZ;
      const flap = Math.sin(t * 4.0 + d.phase);
      d.wr.rotation.z = flap * 0.45;
      d.wl.rotation.z = -flap * 0.45;
      gull.rotation.y = Math.cos(t * 0.16 + d.phase) * 0.35;
    }

    for (const wisp of wisps) {
      const d = wisp.userData;
      wisp.position.x = camera.position.x + wrap(d.baseX - camera.position.x, -380, 380);
      wisp.position.y = d.baseY + Math.sin(t * 0.03 + d.baseX) * 2.0;
      wisp.position.z = d.baseZ;
    }

    foamSparkle.visible = false;
  }

  return {
    update,
    sunDirection: SUN_DIR,
    oceanUniforms,
    sky,
    sunGlow,
    lights: { hemi, key, fill, rim },
    waveHeight,
    clockStart,
  };
}

import * as THREE from 'three';
import { waveHeight } from './waves.js';
import {
  makeBoardFoam,
  makeFoamPuff,
  makeFoamTile,
  makeSprayTexture,
  rng,
} from './textures.js';

function particleMaterial(texture, { additive = false, softness = 1 } = {}) {
  return new THREE.ShaderMaterial({
    uniforms: {
      uMap: { value: texture },
      uPixelScale: { value: 800 },
      uOpacity: { value: 1 },
      uWarm: { value: new THREE.Color('#fff8ea') },
      uSoftness: { value: softness },
    },
    vertexShader: /* glsl */ `
      attribute float aSize;
      attribute float aAlpha;
      uniform float uPixelScale;
      varying float vAlpha;
      void main() {
        vAlpha = aAlpha;
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = aSize * uPixelScale / max(0.001, -mv.z);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform sampler2D uMap;
      uniform vec3 uWarm;
      uniform float uOpacity;
      varying float vAlpha;
      void main() {
        vec4 t = texture2D(uMap, gl_PointCoord);
        float a = t.a * vAlpha * uOpacity;
        if (a < 0.003) discard;
        gl_FragColor = vec4(uWarm, a);
      }
    `,
    transparent: true,
    depthWrite: false,
    blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
  });
}

function createFoamParticles(count = 170) {
  const rand = rng(411);
  const positions = new Float32Array(count * 3);
  const sizes = new Float32Array(count);
  const alphas = new Float32Array(count);
  const data = [];

  for (let i = 0; i < count; i++) {
    data.push({
      x: 0,
      z: 0,
      vx: 0,
      vz: 0,
      age: rand() * 2.5,
      life: 1.4 + rand() * 1.5,
      size: 0.3 + rand() * 0.35,
      spin: rand() * 6.28,
    });
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
  geo.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1));

  const mat = particleMaterial(makeFoamPuff(), { additive: false });
  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  points.renderOrder = 3;

  let cursor = 0;
  let emitAcc = 0;
  const tmp = new THREE.Vector3();

  function spawn(d, state, initial = false) {
    const rand2 = rand;
    const along = (rand2() - 0.5) * 1.2;
    const lag = -1.5 - rand2() * 0.9;
    d.x =
      state.position.x +
      state.forward.x * lag +
      state.right.x * along;
    d.z =
      state.position.z +
      state.forward.z * lag +
      state.right.z * along;
    const outward = Math.sign(along) || 1;
    d.vx = state.right.x * outward * (0.15 + rand2() * 0.45) - state.forward.x * 0.2;
    d.vz = state.right.z * outward * (0.15 + rand2() * 0.45) - state.forward.z * 0.2;
    d.age = initial ? rand2() * d.life * 1.2 : 0;
    d.life = 1.5 + rand2() * 1.7;
    d.size = 0.28 + rand2() * 0.35;
    d.spin = rand2() * 6.28;
  }

  function update(t, dt, state, camera) {
    emitAcc += dt * 72;
    while (emitAcc > 1) {
      emitAcc -= 1;
      const d = data[cursor];
      spawn(d, state);
      cursor = (cursor + 1) % count;
    }

    for (let i = 0; i < count; i++) {
      const d = data[i];
      d.age += dt;
      if (d.age > d.life) {
        spawn(d, state, false);
      }
      d.x += d.vx * dt;
      d.z += d.vz * dt;
      d.vx *= 1 - dt * 0.9;
      d.vz *= 1 - dt * 0.9;

      const u = Math.min(1, d.age / d.life);
      const y = waveHeight(d.x, d.z, t) + 0.035 + Math.sin(t * 2 + d.spin) * 0.008;
      positions[i * 3] = d.x;
      positions[i * 3 + 1] = y;
      positions[i * 3 + 2] = d.z;
      sizes[i] = d.size + u * 0.9;
      alphas[i] = Math.sin(Math.min(1, u) * Math.PI) ** 0.6 * 0.5;
    }

    geo.attributes.position.needsUpdate = true;
    geo.attributes.aSize.needsUpdate = true;
    geo.attributes.aAlpha.needsUpdate = true;

    // keep the point scale in sync with the camera
    const pxScale =
      (window.devicePixelRatio ? Math.min(window.devicePixelRatio, 2) : 1) * 0;
    // pixel scale is supplied by the parent
    void pxScale;
  }

  function setPixelScale(v) {
    mat.uniforms.uPixelScale.value = v;
  }

  return { points, update, setPixelScale, spawnAt: (state) => spawn(data[cursor], state) };
}

function createSpray(count = 150) {
  const rand = rng(931);
  const positions = new Float32Array(count * 3);
  const sizes = new Float32Array(count);
  const alphas = new Float32Array(count);
  const data = [];
  for (let i = 0; i < count; i++) {
    data.push({
      x: 0,
      y: -100,
      z: 0,
      vx: 0,
      vy: 0,
      vz: 0,
      age: 99,
      life: 1,
      size: 0.05,
    });
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
  geo.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1));

  const mat = particleMaterial(makeSprayTexture(), { additive: true });
  mat.uniforms.uOpacity.value = 0.85;
  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  points.renderOrder = 4;

  let cursor = 0;
  let acc = 0;
  let burstTimer = 0.7;

  function emit(state, explosive = false) {
    const d = data[cursor];
    cursor = (cursor + 1) % count;
    const side = rand() > 0.5 ? 1 : -1;
    const forwardOffset = explosive ? 1.35 + rand() * 0.75 : 0.9 + rand() * 0.9;
    const sideOffset = (0.4 + rand() * 0.28) * side;
    d.x =
      state.position.x +
      state.forward.x * forwardOffset +
      state.right.x * sideOffset;
    d.z =
      state.position.z +
      state.forward.z * forwardOffset +
      state.right.z * sideOffset;
    d.y = waveHeight(d.x, d.z, state.time) + 0.09;
    const up = explosive ? 1.8 + rand() * 2.6 : 1.0 + rand() * 2.0;
    d.vx = state.right.x * side * (0.7 + rand() * 1.2) - state.forward.x * (0.3 + rand() * 0.7);
    d.vz = state.right.z * side * (0.7 + rand() * 1.2) - state.forward.z * (0.3 + rand() * 0.7);
    d.vy = up;
    d.age = 0;
    d.life = 0.55 + rand() * 0.65;
    d.size = 0.025 + rand() * 0.055;
  }

  function update(t, dt, state) {
    acc += dt * 24;
    while (acc > 1) {
      acc -= 1;
      emit(state, false);
    }

    burstTimer -= dt;
    if (burstTimer < 0) {
      burstTimer = 2.2 + rand() * 2.3;
      for (let i = 0; i < 18; i++) emit(state, true);
    }

    for (let i = 0; i < count; i++) {
      const d = data[i];
      d.age += dt;
      if (d.age > d.life) {
        alphas[i] = 0;
        sizes[i] = 0.001;
        positions[i * 3 + 1] = -100;
        continue;
      }
      d.vy -= 7.4 * dt;
      d.x += d.vx * dt;
      d.y += d.vy * dt;
      d.z += d.vz * dt;
      const u = d.age / d.life;
      const water = waveHeight(d.x, d.z, t);
      if (d.y < water && d.vy < 0) {
        alphas[i] = 0;
        d.age = d.life + 0.1;
        positions[i * 3 + 1] = -100;
        continue;
      }
      positions[i * 3] = d.x;
      positions[i * 3 + 1] = d.y;
      positions[i * 3 + 2] = d.z;
      sizes[i] = d.size * (0.7 + u * 1.6);
      alphas[i] = (1 - u) * (1 - u) * 0.85;
    }
    geo.attributes.position.needsUpdate = true;
    geo.attributes.aSize.needsUpdate = true;
    geo.attributes.aAlpha.needsUpdate = true;
  }

  function setPixelScale(v) {
    mat.uniforms.uPixelScale.value = v;
  }

  return { points, update, setPixelScale };
}

function createWake(scene, count = 54) {
  const positions = new Float32Array(count * 2 * 3);
  const uvs = new Float32Array(count * 2 * 2);
  const indices = [];
  for (let i = 0; i < count; i++) {
    uvs[i * 4 + 0] = 0;
    uvs[i * 4 + 1] = i / (count - 1);
    uvs[i * 4 + 2] = 1;
    uvs[i * 4 + 3] = i / (count - 1);
    if (i < count - 1) {
      const a = i * 2;
      const b = a + 1;
      const c = a + 2;
      const d = a + 3;
      indices.push(a, c, b, b, c, d);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
  geo.setIndex(indices);

  const mat = new THREE.ShaderMaterial({
    uniforms: {
      uMap: { value: makeFoamTile() },
      uTime: { value: 0 },
      uOpacity: { value: 0.7 },
    },
    vertexShader: /* glsl */ `
      varying vec2 vUv;
      void main() {
        vUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform sampler2D uMap;
      uniform float uTime;
      uniform float uOpacity;
      varying vec2 vUv;
      void main() {
        vec2 uv = vec2(vUv.x * 1.6 + 0.15, vUv.y * 7.0 + uTime * 0.09);
        float a = texture2D(uMap, uv).a;
        float fade = pow(max(0.0, 1.0 - vUv.y), 1.55);
        fade *= smoothstep(0.0, 0.06, vUv.y);
        float edge = smoothstep(0.0, 0.18, vUv.x) * (1.0 - smoothstep(0.82, 1.0, vUv.x));
        a *= fade * edge * uOpacity;
        if (a < 0.004) discard;
        gl_FragColor = vec4(vec3(1.0, 0.98, 0.94), a * 0.85);
      }
    `,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geo, mat);
  mesh.frustumCulled = false;
  mesh.renderOrder = 2;
  scene.add(mesh);

  const history = [];
  for (let i = 0; i < count; i++) {
    history.push({ x: 0, z: 0, rightX: 0, rightZ: 1 });
  }
  let acc = 0;

  function update(t, dt, state) {
    mat.uniforms.uTime.value = t;
    acc += dt;
    const interval = 1 / 24;
    while (acc >= interval) {
      acc -= interval;
      history.pop();
      history.unshift({
        x: state.position.x - state.forward.x * 1.55,
        z: state.position.z - state.forward.z * 1.55,
        rightX: state.right.x,
        rightZ: state.right.z,
      });
    }

    for (let i = 0; i < count; i++) {
      const h = history[i];
      const v = i / (count - 1);
      const w = 0.55 + v * 2.0;
      const y = waveHeight(h.x, h.z, t) + 0.06;
      const idx = i * 6;
      positions[idx + 0] = h.x - h.rightX * w;
      positions[idx + 1] = y;
      positions[idx + 2] = h.z - h.rightZ * w;
      positions[idx + 3] = h.x + h.rightX * w;
      positions[idx + 4] = y;
      positions[idx + 5] = h.z + h.rightZ * w;
    }
    geo.attributes.position.needsUpdate = true;
    mesh.position.set(0, 0, 0);
  }

  return { mesh, update };
}

export function createParticles(scene, boardGroup) {
  const rand = rng(74);
  const foam = createFoamParticles();
  const spray = createSpray();
  const wake = createWake(scene);
  scene.add(foam.points);
  scene.add(spray.points);

  const haloMat = new THREE.MeshBasicMaterial({
    map: makeBoardFoam(),
    transparent: true,
    opacity: 0.55,
    depthWrite: false,
    color: new THREE.Color('#ffffff'),
    blending: THREE.NormalBlending,
  });
  const haloGroup = new THREE.Group();
  const halo = new THREE.Mesh(new THREE.PlaneGeometry(5.6, 2.3), haloMat);
  halo.rotation.x = -Math.PI / 2;
  halo.position.set(-0.8, 0.045, 0);
  halo.renderOrder = 2;
  haloGroup.add(halo);
  haloGroup.rotation.y = 0;
  scene.add(haloGroup);

  const state = {
    position: new THREE.Vector3(),
    forward: new THREE.Vector3(1, 0, 0),
    right: new THREE.Vector3(0, 0, 1),
    time: 0,
  };

  function setPixelScale(camera, renderer) {
    const size = renderer.getDrawingBufferSize(new THREE.Vector2());
    const scale = size.y / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2));
    foam.setPixelScale(scale);
    spray.setPixelScale(scale);
  }

  function update(t, dt, board) {
    state.time = t;
    state.position.copy(board.position);
    state.forward.copy(board.forward);
    state.right.copy(board.right);

    foam.update(t, dt, state);
    spray.update(t, dt, state);
    wake.update(t, dt, state);

    haloGroup.position.set(
      board.position.x,
      waveHeight(board.position.x, board.position.z, t) + 0.06,
      board.position.z,
    );
    haloGroup.rotation.y = board.yaw;
    haloMat.opacity = 0.48 + Math.sin(t * 1.8) * 0.06;
    // break up the halo with a tiny drift
    halo.position.z = Math.sin(t * 0.7) * 0.06;

    void boardGroup;
    void rand;
  }

  return { update, setPixelScale };
}

import * as THREE from 'three';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
import { createSurfingPelican } from './src/pelican.js';
import { createEnvironment, SUN_DIR } from './src/environment.js';
import { createParticles } from './src/particles.js';
import { makeGrainDataURL } from './src/textures.js';
import { waveGradient, waveHeight } from './src/waves.js';

const app = document.getElementById('app');

const renderer = new THREE.WebGLRenderer({
  antialias: true,
  powerPreference: 'high-performance',
  alpha: false,
  stencil: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.6));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.outputColorSpace = THREE.SRGBColorSpace;
app.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color('#e9c4a8');

const camera = new THREE.PerspectiveCamera(
  40,
  window.innerWidth / window.innerHeight,
  0.1,
  1200,
);

const environment = createEnvironment(scene, camera);
const surfer = createSurfingPelican();
scene.add(surfer.group);
const particles = createParticles(scene);

// ---------------------------------------------------------------- post fx
const composer = new EffectComposer(renderer);
const renderPass = new RenderPass(scene, camera);
composer.addPass(renderPass);

const bloom = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  0.44,
  0.72,
  0.86,
);
composer.addPass(bloom);
composer.addPass(new OutputPass());

// Multisampled offscreen buffer (WebGL2)
if (composer.renderTarget1) composer.renderTarget1.samples = 4;
if (composer.renderTarget2) composer.renderTarget2.samples = 4;

// ------------------------------------------------------------------ state
const SPEED = 3.35;
const board = {
  position: new THREE.Vector3(),
  forward: new THREE.Vector3(1, 0, 0),
  right: new THREE.Vector3(0, 0, 1),
  yaw: 0,
};

surfer.group.rotation.order = 'YXZ';

const grad = { x: 0, z: 0 };
const pointer = new THREE.Vector2(0, 0);
const pointerTarget = new THREE.Vector2(0, 0);
const lookTarget = new THREE.Vector3(0, 1.7, 0);
const desiredCam = new THREE.Vector3();
const baseOffset = new THREE.Vector3(2.45, 2.42, 7.9);

const clock = new THREE.Clock();
let simTime = 0;
let started = false;

function resetPointer() {
  pointerTarget.set(0, 0);
}

window.addEventListener('pointermove', (event) => {
  pointerTarget.x = (event.clientX / window.innerWidth) * 2 - 1;
  pointerTarget.y = (event.clientY / window.innerHeight) * 2 - 1;
});
window.addEventListener('pointerleave', resetPointer);
window.addEventListener('blur', resetPointer);

function setSizes() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.6));
  renderer.setSize(w, h);
  composer.setPixelRatio(renderer.getPixelRatio());
  composer.setSize(w, h);
  bloom.setSize(w, h);
  particles.setPixelScale(camera, renderer);
}

window.addEventListener('resize', setSizes);

const grain = document.getElementById('grain');
if (grain) grain.style.backgroundImage = `url(${makeGrainDataURL()})`;

// ------------------------------------------------------------------ motion
function updateBoard(t) {
  const x = t * SPEED;
  const z =
    Math.sin(x * 0.031) * 2.3 +
    Math.sin(t * 0.13 + 0.4) * 0.45;
  const vz =
    Math.cos(x * 0.031) * 0.031 * 2.3 * SPEED +
    Math.cos(t * 0.13 + 0.4) * 0.13 * 0.45;
  const vx = SPEED;
  const yaw = -Math.atan2(vz, vx);

  const y = waveHeight(x, z, t) + 0.03;
  board.position.set(x, y, z);
  board.yaw = yaw;
  board.forward.set(Math.cos(yaw), 0, -Math.sin(yaw));
  board.right.set(Math.sin(yaw), 0, Math.cos(yaw));

  waveGradient(x, z, t, grad);

  const pitch = Math.atan(grad.x);
  const roll = Math.atan(-grad.z);
  const bank = Math.sin(t * 0.23 + 1.4) * 0.035;
  surfer.group.position.copy(board.position);
  surfer.group.rotation.set(roll + bank, yaw, pitch);

  return { pitch, roll };
}

function updateCamera(t, dt) {
  pointer.lerp(pointerTarget, 1 - Math.exp(-dt * 3.0));

  // slow, cinematic breathing orbit + a gentle opening push-in
  const intro = 1 + 0.55 * Math.exp(-t * 0.22);
  const driftX = Math.sin(t * 0.073) * 0.55 + Math.sin(t * 0.021 + 1.7) * 0.35;
  const driftY = Math.sin(t * 0.11 + 0.6) * 0.22;
  const driftZ = Math.sin(t * 0.061 + 2.1) * 0.4;

  desiredCam.set(
    board.position.x + (baseOffset.x + driftX) * intro + pointer.x * 0.8,
    board.position.y + (baseOffset.y + driftY) * intro + pointer.y * -0.35,
    board.position.z + (baseOffset.z + driftZ) * intro,
  );

  const lerp = 1 - Math.exp(-dt * (started ? 2.4 : 20));
  camera.position.lerp(desiredCam, lerp);

  const target = new THREE.Vector3(
    board.position.x + 0.42 + pointer.x * 0.22,
    board.position.y + 1.66 + pointer.y * -0.1,
    board.position.z,
  );
  lookTarget.lerp(target, 1 - Math.exp(-dt * 3.2));
  camera.lookAt(lookTarget);
}

function tick() {
  const dt = Math.min(clock.getDelta(), 0.05);
  simTime += dt;
  const t = simTime;

  const slopes = updateBoard(t);
  surfer.update(t, dt, slopes.pitch, slopes.roll);
  updateCamera(t, dt);
  environment.update(t, dt, board.position);
  particles.update(t, dt, board);

  composer.render();

  if (!started) {
    started = true;
    camera.position.copy(desiredCam);
    lookTarget.set(
      board.position.x + 0.42,
      board.position.y + 1.66,
      board.position.z,
    );
    document.body.classList.add('is-ready');
  }
}

renderer.setAnimationLoop(tick);

// Start with a sensible framing so the very first frame is already composed.
updateBoard(0);
camera.position.set(
  board.position.x + baseOffset.x * 1.4,
  board.position.y + baseOffset.y * 1.4,
  board.position.z + baseOffset.z * 1.4,
);
lookTarget.set(board.position.x + 0.42, board.position.y + 1.66, board.position.z);
camera.lookAt(lookTarget);
setSizes();

:root {
  --ink: #fdf4e6;
  --ink-dim: rgba(253, 244, 230, 0.66);
  --coral: #e46a4c;
  --deep: #173a43;
  --serif: "Bodoni 72", Didot, "Iowan Old Style", Georgia, "Times New Roman", serif;
  --sans: "Helvetica Neue", Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #d9b092;
}

body {
  font-family: var(--sans);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

#app,
#app canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

#app canvas {
  outline: none;
}

/* ------------------------------------------------------------------ overlays */
.vignette,
.grain {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}

.vignette {
  background:
    radial-gradient(ellipse 82% 68% at 52% 46%, transparent 35%, rgba(14, 33, 39, 0.22) 72%, rgba(10, 23, 28, 0.48) 100%),
    linear-gradient(180deg, rgba(13, 32, 40, 0.2) 0%, transparent 18%, transparent 72%, rgba(13, 28, 33, 0.3) 100%);
  mix-blend-mode: multiply;
}

.grain {
  opacity: 0.5;
  background-repeat: repeat;
  background-size: 128px 128px;
  mix-blend-mode: soft-light;
  z-index: 3;
}

/* ------------------------------------------------------------------- layout */
.ui {
  position: fixed;
  inset: 0;
  z-index: 4;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: clamp(22px, 3.4vw, 48px) clamp(22px, 3.8vw, 58px);
  pointer-events: none;
  text-shadow: 0 1px 24px rgba(19, 38, 44, 0.22);
}

.top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  opacity: 0;
  transform: translateY(-10px);
  transition: opacity 1.6s ease 0.9s, transform 1.6s cubic-bezier(0.2, 0.7, 0.2, 1) 0.9s;
}

.brand,
.edition {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

.brand-mark {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 0 3px rgba(228, 106, 76, 0.2);
}

.edition {
  color: var(--ink-dim);
  gap: 10px;
}

.rule-short {
  display: block;
  width: 30px;
  height: 1px;
  background: rgba(253, 244, 230, 0.38);
}

.title-block {
  position: absolute;
  left: clamp(22px, 3.8vw, 58px);
  bottom: clamp(84px, 12vh, 132px);
  max-width: min(560px, 74vw);
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 1.9s ease 0.35s, transform 2s cubic-bezier(0.16, 0.8, 0.2, 1) 0.35s;
}

.eyebrow {
  margin: 0 0 18px;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: rgba(255, 238, 218, 0.78);
}

.eyebrow::before {
  content: "";
  display: inline-block;
  width: 34px;
  height: 1px;
  margin: 0 14px 3px 0;
  background: var(--coral);
}

h1 {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(54px, 8.6vw, 118px);
  font-weight: 400;
  line-height: 0.84;
  letter-spacing: -0.035em;
  color: var(--ink);
}

h1 em {
  display: inline-block;
  margin-left: clamp(10px, 2.2vw, 38px);
  font-weight: 400;
  color: #ffd9b2;
  letter-spacing: -0.025em;
}

.sub {
  margin: clamp(18px, 2.6vh, 30px) 0 0;
  max-width: 30ch;
  font-size: 12px;
  line-height: 1.7;
  letter-spacing: 0.035em;
  color: var(--ink-dim);
}

.bottom {
  position: absolute;
  left: clamp(22px, 3.8vw, 58px);
  right: clamp(22px, 3.8vw, 58px);
  bottom: clamp(22px, 3.2vw, 42px);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 1.6s ease 1.15s, transform 1.6s ease 1.15s;
}

.coords {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: rgba(253, 244, 230, 0.56);
}

.coords span:first-child {
  color: rgba(253, 244, 230, 0.82);
}

.hint {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: rgba(253, 244, 230, 0.62);
}

.hint-dot {
  position: relative;
  width: 22px;
  height: 1px;
  background: rgba(253, 244, 230, 0.4);
}

.hint-dot::after {
  content: "";
  position: absolute;
  top: -2px;
  left: 0;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--coral);
  animation: drift 5.4s ease-in-out infinite;
}

@keyframes drift {
  0%,
  100% {
    transform: translateX(0);
    opacity: 0.45;
  }
  50% {
    transform: translateX(17px);
    opacity: 1;
  }
}

/* ------------------------------------------------------------------- loader */
.loader {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at 50% 42%, #f5cdb0 0%, #dfa98c 44%, #a26f62 100%);
  transition: opacity 1.5s ease 0.1s, visibility 1.5s;
}

.loader-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 22px;
  color: rgba(255, 246, 232, 0.88);
}

.loader-inner p {
  margin: 0;
  font-size: 10px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
}

.loader-sun {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #ffdfb2;
  box-shadow:
    0 0 40px 10px rgba(255, 206, 150, 0.55),
    0 0 100px 34px rgba(255, 181, 120, 0.25);
  animation: breathe 2.8s ease-in-out infinite;
}

@keyframes breathe {
  0%,
  100% {
    transform: scale(0.92);
    opacity: 0.8;
  }
  50% {
    transform: scale(1.06);
    opacity: 1;
  }
}

/* -------------------------------------------------------------------- ready */
body.is-ready .top,
body.is-ready .bottom,
body.is-ready .title-block {
  opacity: 1;
  transform: translateY(0);
}

body.is-ready .loader {
  opacity: 0;
  visibility: hidden;
}

/* ----------------------------------------------------------------- responsive */
@media (max-width: 720px) {
  .ui {
    padding: 20px;
  }

